INSERT INTO `products` (`id`, `slug`, `name_en`, `name_bn`, `details`, `main_image`, `main_menu_id`, `sub_menu_id`, `child_menu_id`, `price`, `sale_price`, `sale_from_dates`, `Sale_to_dates`, `tax_status`, `tax_class`, `stock_management`, `stock_status`, `link_status`, `sold_individually`, `weight_kg`, `length`, `width`, `height`, `site_view_status`, `published_site`, `festive_collection`, `new_arrivals`, `patchwork`, `feature`, `highlight`, `bottom_fastive`, `product_serial`, `product_barcode`, `created_at`, `updated_at`) VALUES
(366, 'kishori-skirt', 'Kishori Skirt', 'কিশোরী স্কার্ট', '<p>A free-size cotton skirt, 36&Prime; long, with an attached inner and a beautifully detailed border.</p>', 'gallery/SkPrnfG0ZJeACUSMfQ7tDWCV0SOnMq7bHH1KbDQF.jpg', 16, 21, NULL, 2040.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'N', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'highlight-one', 'undefined', NULL, '1122584604609', NULL, NULL),
(367, 'nimki-chik', 'Nimki chik', 'নিমকি চিক', '<p><span style=\"color: #ba372a;\">Wooden beads</span><br>A handcrafted ethnic mala made with &nbsp;wooden beads.</p>\r\n<p>&nbsp;</p>\r\n<p>Note:<br>Colors of the beads will differ in each mala.</p>', 'gallery/3qh1iu72fCPOohK5OosaoMxJs8mg2swZZFCWNIfc.jpg', 21, 22, NULL, 700.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'N', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'highlight-two', 'undefined', NULL, '1122162943243', NULL, NULL),
(368, 'madhobi', 'Madhobi', 'মাধবী', '<div class=\"elementor-element elementor-element-6281592 elementor-widget elementor-widget-jet-listing-dynamic-terms\" data-id=\"6281592\" data-element_type=\"widget\" data-widget_type=\"jet-listing-dynamic-terms.default\">\r\n<div class=\"elementor-widget-container\"><span style=\"color: #ba372a;\">Top</span></div>\r\n</div>\r\n<div class=\"elementor-element elementor-element-368e751 elementor-widget__width-initial elementor-widget elementor-widget-jet-single-excerpt\" data-id=\"368e751\" data-element_type=\"widget\" data-widget_type=\"jet-single-excerpt.default\">\r\n<div class=\"elementor-widget-container\">\r\n<div class=\"elementor-jet-single-excerpt jet-woo-builder\">\r\n<div class=\"woocommerce-product-details__short-description\">\r\n<p>A sleeveless (Extra sleeves, five inches long, will be attached) soft and comfortable cotton top with a relaxed, easygoing style.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', 'gallery/Ttv2Zv3BBuBLiUFirGLPgkvj1PiRO5Klwsx2EMKu.jpg', 16, 23, NULL, 770.00, NULL, NULL, NULL, 'Standrnd', 'Taxable', '0', 'undefined', 'Read More', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'highlight-three', 'undefined', NULL, '1122584498440', NULL, NULL),
(369, 'tama-8', 'Tama 8', 'তামা ৮', '<p><span style=\"color: #ba372a;\">Copper, Wooden beads</span><br>A beautifully crafted long copper choker with wooden beads, blending rustic charm with elegant style.</p>', 'gallery/lApGXpVLwP7z0eBFs4SCcxM1jYxdZFyfnuHvmfQK.jpg', 21, 24, NULL, 800.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'undefined', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'highlight-four', 'undefined', NULL, '1122293333951', NULL, NULL),
(370, 'slit-button-pant', 'Slit button Pant', 'স্লিট বাটন প্যান্ট', '<p>Free-size cotton pant with subtle side patchwork pocket detailing for an easy, stylish fit.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>NOTE:</strong> Patchwork is a craft of needlework in which small pieces of cloth in different designs, patterns, colors, or textures are sewed together. Each and every patch work is different and unique. The designs may not be identically same.<br>-khut</p>', 'gallery/yVLe6I3DmZC5Fx3eYQ3veWef0jziRcK4P4GhT4Xb.jpg', 16, 25, NULL, 1830.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'undefined', 'Read More', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'Y', 'Y', 'Feature Two', 'undefined', 'undefined', NULL, '1122239684192', NULL, NULL),
(371, 'srotoshwini', 'Srotoshwini', 'স্রোতস্বিনী', '<p><span style=\"color: #ba372a;\">Cotton Saree</span></p>\r\n<p><br>A Handloom cotton saree in sea-green and blue hues, with floral blocks on the achol and dense handstitched threadwork on the borders.</p>', 'gallery/mlUo2xhqxAGwKOwHuArMG6vLYRNhqfp6mueRPVfT.jpg', 16, 20, 9, 2750.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'undefined', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'undefined', 'undefined', NULL, '1122596555647', NULL, NULL),
(372, 'bilbopotro', 'Bilbopotro', 'বিল্বপত্র', '<p><span style=\"color: #ba372a;\">Cotton Saree</span></p>\r\n<p><br>A soft handloom cotton saree with a red border, adorned with block prints, and an achol delicately touched with handstich in the shape of bel leaves.</p>', 'gallery/VtJtv81AV5Gqd95334iypv6jCed2Re6aWFJSoMCr.jpg', 16, 20, 9, 1650.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'undefined', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'undefined', 'undefined', NULL, '1122580105650', NULL, NULL),
(373, 'dhoritri', 'Dhoritri', 'ধরিত্রী', '<p><span style=\"color: #ba372a;\">Cotton Saree</span></p>\r\n<p><br>A cotton saree featuring Padma block prints, paired with a hand-stitched flower and block design on the achol.<br>Elegant and detailed, it blends traditional block work with fine craftsmanship.</p>', 'gallery/OSg7QaRhZ1pkqiZfgVntCtbKEJxFeNOPdZqxQVk3.jpg', 16, 20, 9, 2200.00, NULL, NULL, NULL, 'Standrnd', 'Taxable', '0', 'N', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'undefined', 'undefined', NULL, '1122571478169', NULL, NULL),
(374, 'ayeshi', 'Ayeshi', 'আয়েশী', '<p><span style=\"color: #ba372a;\">Cotton Saree</span></p>\r\n<p>Cotton Saree &ndash; features intricate block prints, carefully stamped along with handstich ,bringing alive timeless motifs and patterns inspired by nature, culture, and folklore.</p>\r\n<p>Soft, breathable, and lightweight, this saree ensures comfort and effortless elegance. Its fine weave makes it ideal for daily wear or any special moment. A timeless choice for a graceful look.</p>', 'gallery/ITjTkPIWnDZ8YYe6PWcSsnbPMnxCqudqfp8aE74D.jpg', 16, 20, 9, 1980.00, NULL, NULL, NULL, 'Standrnd', 'Taxable', '0', 'N', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'undefined', 'undefined', NULL, '1122571479470', NULL, NULL),
(375, 'dipanjoli', 'Dipanjoli', 'দীপাঞ্জলী', '<p><span style=\"color: #ba372a;\">Cotton Saree</span></p>\r\n<p>A cotton saree featuring half-body Padma block prints, paired with a hand-stitched Padma block design on the achol.<br>Elegant and detailed, it blends traditional block work with fine craftsmanship.</p>', 'gallery/ZKAJMjIRYmXmmY0EvSQgqz4i8IYllyQ0aixLQMj4.jpg', 16, 20, 9, 2200.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'N', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'undefined', 'undefined', NULL, '1122555011467', NULL, NULL),
(376, 'obhilash', 'Obhilash', 'অভিলাষ', '<p><span style=\"color: #ba372a;\">Cotton, Wax print Saree</span></p>\r\n<p>A wax print cotton saree, adorned with block prints, a patchwork achol, and fine hand-stitched detailing.</p>\r\n<p>Patchwork is a craft of needlework in which small pieces of cloth in different designs, patterns, colors, or textures are sewed together. Each and every patch work is different and unique .The designs may not be identically same.<br>If you have any confusion please feel free to ask question/s before confirming your order. We are here to clear any confusion related to our product..<br>-khut</p>', 'gallery/zWCPWLzPrvUTy8xVu5ZmESjUKBbIvM3H025WxGsX.jpg', 16, 20, 9, 3080.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'N', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'undefined', 'undefined', NULL, '1122571479760', NULL, NULL),
(377, 'akangkha', 'Akangkha', 'আকাঙ্ক্ষা', '<p><span style=\"color: #843fa1;\">Cotton Saree</span></p>\r\n<p>A soft cotton saree crafted with shibori work, dyed in natural colors, detailed with block prints and fine hand-stitched touches.</p>', 'gallery/KTzD8Nc8m7h5eeRDS7tozKTBwpJoXDMHNDn7fFBi.jpg', 16, 20, 9, 3080.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'N', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'undefined', 'undefined', NULL, '1122518034557', NULL, NULL),
(378, 'fulpakhi', 'Fulpakhi', 'ফুলপাখি', '<p><span style=\"color: #ba372a;\">Cotton Saree</span></p>\r\n<p>Cotton Saree-Endi Achol _ features intricate block prints, carefully stamped along with handstich ,bringing alive timeless motifs and patterns inspired by nature, culture, and folklore.</p>\r\n<p>Soft, breathable, and lightweight, this saree ensures comfort and effortless elegance. Its fine weave makes it ideal for daily wear or any special moment. A timeless choice for a graceful look.</p>', 'gallery/NrELgSDWdLVTEg4E7vzXxjGaXTIMribX7VeuzC25.jpg', 16, 20, 9, 2640.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'undefined', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'undefined', 'undefined', NULL, '1122555015939', NULL, NULL),
(379, 'rupshikha', 'Rupshikha', 'রূপশিখা', '<p>Cotton Saree</p>\r\n<p>Cotton Saree &ndash; features intricate block prints, carefully stamped along with handstich ,bringing alive timeless motifs and patterns inspired by nature, culture, and folklore.</p>\r\n<p>Soft, breathable, and lightweight, this saree ensures comfort and effortless elegance. Its fine weave makes it ideal for daily wear or any special moment. A timeless choice for a graceful look.</p>', 'gallery/KcXnV4HgftuOxP4Bcsasqlrt45h0hGWhJDFurDOJ.jpg', 16, 20, 9, 1980.00, NULL, NULL, NULL, 'Cloths', 'Taxable', '0', 'N', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'undefined', 'undefined', NULL, '1122555011955', NULL, NULL),
(380, 'jolfota', 'Jolfota', 'জলফোঁটা', '<p><span style=\"color: #ba372a;\">Cotton Saree</span></p>\r\n<p>Cotton Saree-Endi Achol _ features intricate block prints, carefully stamped along with handstich ,bringing alive timeless motifs and patterns inspired by nature, culture, and folklore.</p>\r\n<p>Soft, breathable, and lightweight, this saree ensures comfort and effortless elegance. Its fine weave makes it ideal for daily wear or any special moment. A timeless choice for a graceful look.</p>', 'gallery/3tf1W9Ji7bqcsQzY0cYbLxpsla09GCzyj70u3aEm.jpg', 16, 20, 9, 2950.00, NULL, NULL, NULL, 'Standrnd', 'Taxable', '0', 'undefined', 'Add to Cart', '0', NULL, NULL, NULL, NULL, 'Y', 'Y', 'N', 'N', 'N', 'undefined', 'undefined', 'undefined', NULL, '1122617251312', NULL, NULL),
